import math

def bad_windows(samples, window_s, p, limit_ms):
    groups = {}
    for ts, ms in samples:
        groups.setdefault(ts // window_s, []).append(ms)
    bad = []
    for w, vals in groups.items():
        s = sorted(vals)
        v = s[max(math.ceil(p / 100 * len(s)), 1) - 1]
        if v > limit_ms:
            bad.append(w * window_s)
    return sorted(bad)

