from collections import Counter

def throughput(end_times_ms):
    buckets = Counter(t // 1000 for t in end_times_ms)
    span = max(buckets) - min(buckets) + 1
    return {'avg': round(len(end_times_ms) / span, 2), 'peak': max(buckets.values())}
